@startuml

class EBike {
}

class Frame {
  + material : string
}

class DriveSystem {
}

class Motor {}

class Controller {
  + state : ControllerState
}

abstract class AdvancedController extends Controller {
  + next_inspection_date : date
}

class BasicController extends Controller {}

class Battery {
  + energy_wh : float
}

enum ControllerState {
  On
  Off
  Charging
}

EBike "1" *-- "1" Frame
EBike "1" *-- "1" DriveSystem
EBike "1" *-- "1" Controller
EBike "0..1" -- "0..1" Battery
DriveSystem "1" *-- "1" Motor
Controller "1" --> "1" DriveSystem
Controller "0..1" --> "0..1" Battery

@enduml

